];

function PriceChart({ data, color, name }) {
  const canvasRef = useRef();
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || !window.Chart) return;
    const existing = window.Chart.getChart(canvas);
    if (existing) existing.destroy();
    const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
    new window.Chart(canvas, {
      type: 'line',
      data: {
        labels: months,
        datasets: [{
          label: `${name} Price (₹/Q)`,
          data,
          borderColor: color,
          backgroundColor: color + '15',
          borderWidth: 2.5,
          fill: true,
          tension: 0.4,
          pointRadius: 3,
          pointBackgroundColor: color,
        }]
      },
      options: {
        responsive: true, maintainAspectRatio: false,
        plugins: { legend: { display: false }, tooltip: { backgroundColor: '#0a1a0f', borderColor: color, borderWidth: 1, titleColor: '#fff', bodyColor: '#9ca3af' } },
        scales: {
          x: { grid: { color: 'rgba(255,255,255,0.05)' }, ticks: { color: '#6b7280', font: { size: 10 } } },
          y: { grid: { color: 'rgba(255,255,255,0.05)' }, ticks: { color: '#6b7280', font: { size: 10 }, callback: v => '₹' + v } }
        }
      }
    });
  }, [data, color, name]);
  return <div className="h-48"><canvas ref={canvasRef} /></div>;
}

function DemandBadge({ demand }) {
  const map = { 'Very High': 'text-green-300 bg-green-900/30 border-green-700/40', High: 'text-green-400 bg-green-900/20 border-green-800/30', Medium: 'text-yellow-400 bg-yellow-900/20 border-yellow-800/30', Low: 'text-red-400 bg-red-900/20 border-red-800/30' };
  return <span className={`text-xs px-2 py-0.5 rounded-full border font-medium ${map[demand]}`}>{demand}</span>;
}

